export const BODY: string = "\n<p>صور GIF المتحركة هي أثقل صور الويب. مقطع عشر ثوانٍ قد يزن ميغابايتات عدة، فيبطئ الصفحة ويرفضه ديسكورد.</p>\n<p>ضغط GIF مختلف عن ضغط الصورة. GIF تحمل إطارات ولوحات ألوان وتوقيتًا، وكل عنصر منها يؤثر في الحجم.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/daght-gif/\">ضاغط GIF</a>، وماذا يفعل كل إعداد، وكيف تصنع GIF صغيرًا دون إفساده.</p>\n<h2 id=\"why-gifs-are-big\">لماذا صور GIF كبيرة جدًا؟</h2>\n<p>GIF كبيرة لأنها تخزن كل إطار كصورة كاملة تقريبًا. مقطع عشر ثوانٍ بمعدل 15 إطارًا في الثانية يعني 150 إطارًا في ملف واحد.</p>\n<p>إضافة إلى ذلك، لوحة الألوان المحدودة بـ256 لونًا تجعل الضغط أقل كفاءة من صيغ الفيديو الحديثة. لذلك تنمو ملفات GIF بسرعة.</p>\n<h2 id=\"how-gif-compression-works\">كيف يعمل ضغط GIF؟</h2>\n<p>يعمل ضغط GIF بثلاث طرق: تقليل عدد الألوان في اللوحة، وحذف إطارات زائدة، وتقليص أبعاد الصورة. الجمع بينها يصغّر الملف بشكل كبير.</p>\n<p>الأداة تحافظ على توقيت الحركة والحلقات أثناء الضغط. النتيجة GIF أصغر يتحرك بالطريقة نفسها تقريبًا.</p>\n<h2 id=\"presets-explained\">الإعدادات الجاهزة الثلاثة: خفيف ومتوازن وأقصى تقليص</h2>\n<p>الإعدادات الجاهزة الثلاثة هي: خفيف للجودة العالية، ومتوازن للاستخدام العام، وأقصى تقليص لأصغر حجم ممكن.</p>\n<p>اختر خفيفًا لصور GIF التي تُعرض كبيرة، ومتوازنًا للدردشة والمواقع، وأقصى تقليص عندما يكون الحد صارمًا مثل ديسكورد.</p>\n<h2 id=\"colour-palette\">لوحات الألوان: 256 و128 و64 و32</h2>\n<p>لوحات الألوان 256 و128 و64 و32 تحدد عدد الألوان في GIF. اللوحة الأصغر تعني ملفًا أصغر، لكن بتدرجات أقل سلاسة.</p>\n<p>لصور GIF البسيطة مثل الميمز، تكفي لوحة 64 لونًا. وللصور الفوتوغرافية، ابدأ بـ256 ثم جرّب 128.</p>\n<h2 id=\"frame-rate\">معدل الإطارات وحذف الإطارات</h2>\n<p>معدل الإطارات وحذف الإطارات يؤثران في الحجم والسلاسة معًا. خفض المعدل من 30 إلى 15 إطارًا في الثانية يصغّر الملف إلى النصف تقريبًا.</p>\n<p>لكن الحركة تصبح أقل سلاسة. للحركة السريعة احتفظ بمعدل أعلى، وللحركة البطيئة اخفض المعدل دون أن يلاحظ أحد.</p>\n<h2 id=\"output-scale\">مقياس الإخراج: 100 و85 و75 و50 و25 بالمئة</h2>\n<p>مقياس الإخراج 100 و85 و75 و50 و25 بالمئة يحدد حجم الصورة النهائي. تقليص الأبعاد إلى النصف يصغّر الملف إلى الربع تقريبًا.</p>\n<p>إذا كان GIF يُعرض صغيرًا في الدردشة، فقلّصه إلى 50 بالمئة. لا أحد يلاحظ الفرق في العرض الصغير، والملف يصبح أصغر بكثير.</p>\n<h2 id=\"animation-timing\">كيف تحافظ على توقيت الحركة والحلقات؟</h2>\n<p>للحفاظ على توقيت الحركة والحلقات، يحافظ الضاغط على تأخيرات الإطارات الأصلية. سرعة الحركة تبقى كما هي بعد الضغط.</p>\n<p>إذا حذفت إطارات، فقد يتغير التوقيت قليلًا. راجع الحركة بعد الضغط وتأكد من أنها ما زالت تبدو طبيعية.</p>\n<h2 id=\"transparency-gifs\">الشفافية في صور GIF المضغوطة</h2>\n<p>الشفافية في GIF المضغوطة محفوظة، لكنها حساسة. تقليل لوحة الألوان قد يفسد حواف الشفافية ويجعلها خشنة.</p>\n<p>إذا كان GIF شفافًا، فاستخدم لوحة ألوان أكبر. الجودة أهم من الحجم عندما تكون الشفافية جزءًا من التصميم.</p>\n<h2 id=\"discord-slack\">GIF لديسكورد وسلاك والدردشة</h2>\n<p>GIF لديسكورد وسلاك والدردشة تحتاج أحجامًا صغيرة. ديسكورد يحدد 10 ميغابايت للحسابات المجانية، وسلاك حدود مشابهة.</p>\n<p>اضغط GIF إلى أقل من الحد قبل الرفع. الإعداد المتوازن مع لوحة 128 لونًا يناسب معظم صور الدردشة.</p>\n<h2 id=\"gif-vs-video\">متى تستخدم GIF ومتى تستخدم فيديو؟</h2>\n<p>متى تستخدم GIF ومتى تستخدم فيديو؟ GIF مناسب للمقاطع القصيرة الصامتة التي تتشغل تلقائيًا، مثل ردود الفعل والميمز.</p>\n<p>أما المقاطع الطويلة أو ذات الصوت، فالفيديو أفضل بكثير. ملف MP4 أصغر بكثير من GIF للمقطع نفسه. وللمقارنة الكاملة، اقرأ <a href=\"/ar/blog/gif-vs-webp-vs-mp4-mutaharrika/\">GIF مقابل WebP مقابل MP4: الصور المتحركة مقارنة</a>.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة مع ضغط GIF</h2>\n<p>أكثر الأخطاء شيوعًا البدء من GIF مضغوط أصلًا. كل جولة ضغط تضيف ضررًا، فابدأ دائمًا من الملف الأصلي بأعلى جودة.</p>\n<p>خطأ آخر أن تقلل لوحة الألوان بقوة للصور الفوتوغرافية. التدرجات تتحول إلى شرائط واضحة، وتبدو النتيجة أسوأ بكثير.</p>\n<h2 id=\"gif-file-anatomy\">داخل ملف GIF: الإطارات واللوحات والتأخيرات</h2>\n<p>داخل ملف GIF: إطارات ولوحات ألوان وتأخيرات. كل إطار يحمل صورته وتأخيره، واللوحة تحدد الألوان المتاحة لجميع الإطارات.</p>\n<p>فهم البنية يساعدك على الضغط بذكاء. تقليل الإطارات والألوان هو ما يصغّر الملف فعلًا، لا تغيير أي شيء آخر.</p>\n<h2 id=\"screen-recordings\">تسجيلات الشاشة كصور GIF</h2>\n<p>تسجيلات الشاشة كصور GIF شائعة للشروحات. سجّل الشاشة ثم حوّلها إلى GIF، واضغطها قبل المشاركة.</p>\n<p>لتسجيلات الشاشة، استخدم لوحة ألوان صغيرة ومعدل إطارات منخفض. النص والواجهات لا تحتاج إلى ألوان كثيرة أو حركة سلسة.</p>\n<h2 id=\"reaction-gifs\">صور GIF للتفاعل والميمز</h2>\n<p>صور GIF للتفاعل والميمز تعيش في الدردشة. صغّرها بما يكفي للإرسال السريع، وحافظ على جودة كافية لتكون مضحكة.</p>\n<p>للميمز، لوحة 64 لونًا كافية غالبًا. النص الكبير والحركة البسيطة لا تحتاج إلى ألوان كثيرة.</p>\n<h2 id=\"gif-seo\">GIF وسرعة الصفحة</h2>\n<p>GIF وسرعة الصفحة مرتبطان: GIF ثقيل يبطئ الصفحة أكثر من أي صورة أخرى. صفحة فيها GIF بوزن 5 ميغابايت تحمل ببطء شديد.</p>\n<p>للمواقع، استخدم WebP المتحرك أو فيديو قصيرًا بدل GIF. كلاهما أصغر بكثير ويحسّن سرعة الصفحة.</p>\n<h2 id=\"gif-accessibility\">إمكانية الوصول للصور المتحركة</h2>\n<p>إمكانية الوصول للصور المتحركة تعني احترام من يعانون من الحساسية للحركة. الحركة السريعة والوامضة قد تسبب إزعاجًا أو نوبات.</p>\n<p>تجنب GIF الوامضة بسرعة، وقدّم زر إيقاف عندما يكون ممكنًا. واحترم إعداد تقليل الحركة في نظام المستخدم.</p>\n<h2 id=\"storing-gifs\">كيف تحفظ وتنظّم صور GIF؟</h2>\n<p>لحفظ وتنظيم صور GIF، أنشئ مجلدات حسب الغرض: ردود فعل وميمز وشروحات. سمِّ كل ملف بما يصفه بوضوح.</p>\n<p>احتفظ بالملفات الأصلية منفصلة عن المضغوطة. الأصل مفيد عندما تحتاج إلى إعادة الضغط بإعدادات مختلفة.</p>\n<h2 id=\"keep-practising\">تابع التدريب مع صور GIF حقيقية</h2>\n<p>تابع التدريب مع صور GIF حقيقية. جرّب إعدادات مختلفة على صورك، وقارن النتائج بعينك.</p>\n<p>كل GIF يعلمك شيئًا جديدًا عن التوازن بين الحجم والجودة. وللخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-daght-gif/\">كيفية ضغط GIF</a> وقارن الصيغ في <a href=\"/ar/blog/gif-vs-webp-vs-mp4-mutaharrika/\">GIF مقابل WebP مقابل MP4</a>، أو جرّب <a href=\"/ar/munshi-gif/\">صانع GIF</a> لإنشاء حركتك الخاصة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يغيّر ضغط GIF سرعة تشغيله؟","answer":"لا، الضغط لا يغيّر سرعة التشغيل. سرعة GIF تحددها تأخيرات الإطارات الأصلية، والضغط يحافظ عليها. إذا بدا GIF أبطأ، فقد يكون المتصفح بطيئًا في التحميل لا في التشغيل."},{"question":"لماذا ما زال GIF كبيرًا بعد ضغطه؟","answer":"لأن GIF يحمل إطارات كثيرة وألوانًا محدودة. جرّب تقليل لوحة الألوان إلى 128 أو 64 لونًا، وخفض معدل الإطارات، وتقليص الأبعاد. الجمع بين الثلاثة يصغّر الملف بشكل كبير."},{"question":"ما حجم اللوحة الذي أختاره لصورة GIF فوتوغرافية؟","answer":"لصور GIF الفوتوغرافية، ابدأ بلوحة 256 لونًا ثم جرّب 128. إذا بدت النتيجة جيدة، فاحتفظ بها. اللوحات الأصغر توفر حجمًا لكنها قد تفسد التدرجات."},{"question":"هل يمكنني ضغط GIF ليناسب حدود رفع ديسكورد؟","answer":"نعم. ديسكورد يحدد حجم الملف حسب نوع حسابك: 10 ميغابايت للحسابات المجانية و500 ميغابايت لحسابات نيترو. اضغط GIF إلى أقل من حد حسابك قبل الرفع."},{"question":"هل يعمل ضاغط GIF مع ملفات GIF ذات الإطار الواحد؟","answer":"نعم، يعمل الضاغط مع ملفات GIF ذات الإطار الواحد. يعاملها كصورة ثابتة ويضغطها بنفس الطريقة، مع الحفاظ على الشفافية إن وجدت."},{"question":"ما الفرق بين ضاغط GIF وصانع GIF؟","answer":"ضاغط GIF يصغّر ملف GIF موجود، بينما صانع GIF ينشئ GIF جديدًا من صورك. استخدم الضاغط لملف موجود، والصانع لإنشاء حركة جديدة من صور ثابتة."}];
